// recipe: trader-hostility
// args: mode=s
// returns: ok, mode, traderCount, x, y, hostility, hostile, reputation, buildHealth, handSlot, handItem, handHasGunTag, error, detail
//
// Reads and drives the nearest trader's OWN hostility state. `hostile` is `hostility >= 100` in TraderScript, and the script
// raises it by 50 when the player holds a weapon tagged `gun` in the HAND slot (not a backpack slot) — so this reports the hand
// slot's own item and whether it carries that tag, which is the one fact the earlier attempts were missing.
//   mode=read — the nearest trader and the local body's hand state.
//   mode=hold — puts the backpack item of <index> into the hand through the game's own Body.SwitchHands path when the current
//               hand slot does not already carry it (the native switch, not an assignment), then answers the same reading.
//
// ONE LINE ON PURPOSE: the client's evaluator takes one top-level expression.
((System.Func<string>)(() => { var mode = {{s:mode}}; var index = (int)({{n:index}}); var inv = System.Globalization.CultureInfo.InvariantCulture; var bodies = UnityEngine.Object.FindObjectsOfType(typeof(TraderScript)); if (bodies == null || bodies.Length == 0) { return "{\"ok\":false,\"error\":\"no-trader\"}"; } var camera = PlayerCamera.main; if (camera == null) { return "{\"ok\":false,\"error\":\"no-camera\"}"; } var body = camera.body; if (body == null) { return "{\"ok\":false,\"error\":\"no-body\"}"; } if (mode == "hold") { var target = body.GetItem(index); if (target == null) { return "{\"ok\":false,\"error\":\"no-item-in-slot\",\"detail\":\"" + index.ToString(inv) + "\"}"; } if (body.handSlot != index) { camera.SwitchHands(); } } TraderScript nearest = null; var best = float.MaxValue; for (var i = 0; i < bodies.Length; i++) { var trader = bodies[i] as TraderScript; if (trader == null) { continue; } var distance = UnityEngine.Vector2.Distance(trader.transform.position, body.transform.position); if (distance < best) { best = distance; nearest = trader; } } if (nearest == null) { return "{\"ok\":false,\"error\":\"no-trader\"}"; } var hand = body.GetItem(body.handSlot); var handName = hand == null ? "" : hand.id; var handTag = "none"; if (hand != null && hand.Stats != null) { handTag = hand.Stats.HasTag("gun") ? "gun" : "other"; } var building = nearest.build; var health = building == null ? -1f : building.health; return "{\"ok\":true,\"mode\":\"" + mode + "\",\"traderCount\":" + bodies.Length.ToString(inv) + ",\"x\":" + nearest.transform.position.x.ToString("0.0", inv) + ",\"y\":" + nearest.transform.position.y.ToString("0.0", inv) + ",\"hostility\":" + nearest.hostility.ToString("0.0", inv) + ",\"hostile\":" + (nearest.hostile ? "true" : "false") + ",\"reputation\":" + nearest.reputation.ToString("0.0", inv) + ",\"buildHealth\":" + health.ToString("0.0", inv) + ",\"handSlot\":" + body.handSlot.ToString(inv) + ",\"handItem\":\"" + handName + "\",\"handHasGunTag\":\"" + handTag + "\"}"; }))()